function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = 'accuracy';
  let sortDirection = 'desc';
  let accuracyThreshold = 80; // 精度閾値

  // 店舗選択肢を初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector('#store-filter');
    const stores = tables[1]?.records || [];
    stores.forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = store.店舗名;
      storeSelect.appendChild(option);
    });
  }

  // チャート描画関数
  function drawAccuracyTrendChart(data) {
    const canvas = container.querySelector('#accuracy-trend-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスをクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸を描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データポイントを描画
    if (data.length > 1) {
      ctx.strokeStyle = '#4a9eff';
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((point, index) => {
        const x = padding + (index / (data.length - 1)) * chartWidth;
        const y = canvas.height - padding - (point.accuracy / 100) * chartHeight;

        if (index === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();
    }
  }

  function drawForecastVsActualChart(data) {
    const canvas = container.querySelector('#forecast-vs-actual-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸を描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 予測データ（青線）
    ctx.strokeStyle = '#4a9eff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    data.forEach((point, index) => {
      const x = padding + (index / (data.length - 1)) * chartWidth;
      const y = canvas.height - padding - (point.forecast / Math.max(...data.map(d => Math.max(d.forecast, d.actual)))) * chartHeight;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // 実績データ（オレンジ線）
    ctx.strokeStyle = '#ff6a00';
    ctx.lineWidth = 2;
    ctx.beginPath();
    data.forEach((point, index) => {
      const x = padding + (index / (data.length - 1)) * chartWidth;
      const y = canvas.height - padding - (point.actual / Math.max(...data.map(d => Math.max(d.forecast, d.actual)))) * chartHeight;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '12px sans-serif';
    ctx.fillText('予測', canvas.width - 100, 30);
    ctx.fillText('実績', canvas.width - 100, 50);

    ctx.strokeStyle = '#4a9eff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(canvas.width - 120, 25);
    ctx.lineTo(canvas.width - 105, 25);
    ctx.stroke();

    ctx.strokeStyle = '#ff6a00';
    ctx.beginPath();
    ctx.moveTo(canvas.width - 120, 45);
    ctx.lineTo(canvas.width - 105, 45);
    ctx.stroke();
  }

  // ランキングテーブル再描画
  function renderRankingTable(data) {
    const tbody = container.querySelector('#ranking-tbody');
    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="muted" style="text-align: center; padding: 2rem;">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = data.map((row, index) => `
      <tr data-id="${row.予測結果ID}">
        <td>${index + 1}</td>
        <td>${row.店舗名 || ''}</td>
        <td>${row.商品名 || ''}</td>
        <td style="color: ${row.accuracy >= accuracyThreshold ? '#4a9eff' : '#ff6a00'};">${row.accuracy?.toFixed(2) || '--'}%</td>
        <td>${row.mape?.toFixed(2) || '--'}</td>
        <td>${row.rmse?.toFixed(2) || '--'}</td>
        <td>${row.予測対象日 ? new Date(row.予測対象日).toLocaleDateString() : '--'}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${row.予測結果ID}">詳細分析</button>
        </td>
      </tr>
    `).join('');
  }

  // サマリー更新
  function updateSummary(data) {
    const overallAccuracy = data.length > 0 ? data.reduce((sum, item) => sum + (item.accuracy || 0), 0) / data.length : 0;
    const targetProducts = new Set(data.map(item => item.商品ID)).size;
    const alertCount = data.filter(item => (item.accuracy || 0) < accuracyThreshold).length;

    container.querySelector('#overall-accuracy').textContent = overallAccuracy.toFixed(1) + '%';
    container.querySelector('#target-products').textContent = targetProducts.toString();
    container.querySelector('#alert-count').textContent = alertCount.toString();

    const avgMape = data.length > 0 ? data.reduce((sum, item) => sum + (item.mape || 0), 0) / data.length : 0;
    const avgRmse = data.length > 0 ? data.reduce((sum, item) => sum + (item.rmse || 0), 0) / data.length : 0;

    container.querySelector('#mape-value').textContent = avgMape.toFixed(2);
    container.querySelector('#rmse-value').textContent = avgRmse.toFixed(2);
  }

  // アラート表示
  function updateAlerts(data) {
    const alertPanel = container.querySelector('#alert-panel');
    const template = container.querySelector('#alert-template');
    const noAlerts = container.querySelector('#no-alerts');

    // 既存のアラートをクリア
    const existingAlerts = alertPanel.querySelectorAll('.alert-item:not(#alert-template)');
    existingAlerts.forEach(alert => alert.remove());

    const alerts = data.filter(item => (item.accuracy || 0) < accuracyThreshold);

    if (alerts.length === 0) {
      noAlerts.style.display = 'block';
    } else {
      noAlerts.style.display = 'none';
      alerts.forEach(alert => {
        const alertElement = template.cloneNode(true);
        alertElement.id = '';
        alertElement.style.display = 'block';
        alertElement.querySelector('.alert-store').textContent = alert.店舗名 || '不明';
        alertElement.querySelector('.alert-product').textContent = alert.商品名 || '不明';
        alertElement.querySelector('.alert-accuracy').textContent = (alert.accuracy || 0).toFixed(2);
        alertElement.querySelector('.alert-timestamp').textContent = new Date().toLocaleString();
        alertPanel.appendChild(alertElement);
      });
    }
  }

  // データ読み込み
  async function loadData() {
    try {
      const forecastData = await window.aivicApi.list(4); // 需要予測結果
      if (!forecastData) {
        showError('データの取得に失敗しました。ネットワーク接続を確認してください。');
        return;
      }

      // 予測精度を計算（実績数量がある場合）
      const processedData = forecastData.map(item => {
        let accuracy = null;
        let mape = null;
        let rmse = null;

        if (item.実績数量 && item.予測数量) {
          const error = Math.abs(item.実績数量 - item.予測数量);
          mape = item.実績数量 > 0 ? (error / item.実績数量) * 100 : 0;
          accuracy = Math.max(0, 100 - mape);
          rmse = Math.sqrt(Math.pow(item.実績数量 - item.予測数量, 2));
        }

        return {
          ...item,
          accuracy,
          mape,
          rmse,
          店舗名: getStoreName(item.店舗ID),
          商品名: getProductName(item.商品ID)
        };
      }).filter(item => item.accuracy !== null);

      currentData = processedData;
      applyFilters();
    } catch (error) {
      showError('データの読み込み中にエラーが発生しました。');
    }
  }

  // 店舗名取得
  function getStoreName(storeId) {
    const store = tables[1]?.records?.find(s => s.店舗ID === storeId);
    return store?.店舗名 || '不明';
  }

  // 商品名取得
  function getProductName(productId) {
    const product = tables[2]?.records?.find(p => p.商品ID === productId);
    return product?.商品名 || '不明';
  }

  // フィルター適用
  function applyFilters() {
    const period = parseInt(container.querySelector('#period-filter').value);
    const storeId = container.querySelector('#store-filter').value;
    const category = container.querySelector('#category-filter').value;

    let filteredData = [...currentData];

    // 期間フィルター
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - period);
    filteredData = filteredData.filter(item => 
      !item.予測対象日 || new Date(item.予測対象日) >= cutoffDate
    );

    // 店舗フィルター
    if (storeId) {
      filteredData = filteredData.filter(item => item.店舗ID === storeId);
    }

    // カテゴリフィルター（簡易実装）
    if (category) {
      filteredData = filteredData.filter(item => 
        item.商品名?.includes(category) || false
      );
    }

    // ソート適用
    filteredData.sort((a, b) => {
      const aVal = a[sortColumn] || 0;
      const bVal = b[sortColumn] || 0;
      return sortDirection === 'asc' ? aVal - bVal : bVal - aVal;
    });

    renderRankingTable(filteredData);
    updateSummary(filteredData);
    updateAlerts(filteredData);

    // チャート用データ生成
    const chartData = filteredData.slice(0, 10).map((item, index) => ({
      accuracy: item.accuracy || 0,
      forecast: item.予測数量 || 0,
      actual: item.実績数量 || 0
    }));

    drawAccuracyTrendChart(chartData);
    drawForecastVsActualChart(chartData);
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  // エラー非表示
  function hideError() {
    container.querySelector('#error-message').classList.add('hidden');
  }

  // CSVエクスポート
  function exportCSV() {
    if (currentData.length === 0) {
      alert('エクスポートするデータがありません。');
      return;
    }

    const headers = ['順位', '店舗名', '商品名', '精度(%)', 'MAPE', 'RMSE', '期間'];
    const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
      currentData.map((row, index) => [
        index + 1,
        `"${row.店舗名 || ''}"`,
        `"${row.商品名 || ''}"`,
        (row.accuracy || 0).toFixed(2),
        (row.mape || 0).toFixed(2),
        (row.rmse || 0).toFixed(2),
        row.予測対象日 ? new Date(row.予測対象日).toLocaleDateString() : ''
      ].join(',')).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `予測精度監視_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // ソート処理
  function handleSort(column) {
    if (sortColumn === column) {
      sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      sortColumn = column;
      sortDirection = 'desc';
    }

    // ソートインジケーター更新
    container.querySelectorAll('.sort-indicator').forEach(indicator => {
      indicator.textContent = '';
    });

    const indicator = container.querySelector(`#sort-${column} .sort-indicator`);
    if (indicator) {
      indicator.textContent = sortDirection === 'asc' ? '↑' : '↓';
    }

    applyFilters();
  }

  // 初期化
  initStoreOptions();

  // 初期データ表示
  if (tables[4]?.records) {
    currentData = tables[4].records.map(item => ({
      ...item,
      accuracy: Math.random() * 40 + 60, // サンプル精度データ
      mape: Math.random() * 20 + 5,
      rmse: Math.random() * 10 + 2,
      店舗名: getStoreName(item.店舗ID),
      商品名: getProductName(item.商品ID)
    }));
    applyFilters();
  }

  // 実際のデータを読み込み
  loadData();

  // イベントリスナー
  container.querySelector('#btn-filter').addEventListener('click', applyFilters);

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  container.querySelector('#btn-report').addEventListener('click', () => {
    try {
      exportCSV();
    } catch (error) {
      showError('レポート出力に失敗しました。再度お試しください。');
    }
  });

  container.querySelector('#btn-retry').addEventListener('click', () => {
    hideError();
    loadData();
  });

  // ソートイベント
  ['rank', 'store', 'product', 'accuracy', 'mape', 'rmse', 'period'].forEach(column => {
    const header = container.querySelector(`#sort-${column}`);
    if (header) {
      header.addEventListener('click', () => handleSort(column));
    }
  });

  // 行レベル操作
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      // 詳細分析画面への遷移（相関分析・比較分析画面を使用）
      window.showScreen('scr-1778591822586');
    }
  });
}
